def comparison(subrows):
 result=[]
 for identity,threshold in [('B',policy['threshold']),('baseline',policy['baseline_threshold'])]:
  pairs=[(int(r['late']),int(r['order_amount']>=threshold)) for r in subrows]
  fp=sum(y==0 and p==1 for y,p in pairs);tn=sum(y==0 and p==0 for y,p in pairs);fn=sum(y==1 and p==0 for y,p in pairs);tp=sum(y==1 and p==1 for y,p in pairs)
  fpr=fp/(fp+tn) if fp+tn else None;fnr=fn/(fn+tp) if fn+tp else None
  cost=policy['deployment_probabilities']['0']*fpr*policy['error_costs']['FP']+policy['deployment_probabilities']['1']*fnr*policy['error_costs']['FN'] if fpr is not None and fnr is not None else None
  result.append(dict(identity=identity,FP=fp,TN=tn,FN=fn,TP=tp,actual_negatives=fp+tn,actual_positives=fn+tp,FPR=fpr,FNR=fnr,expected_error_cost=cost,requirements={k:(v<=policy['requirements'][k] if v is not None else None) for k,v in [('max_FPR',fpr),('max_FNR',fnr),('max_expected_error_cost',cost)]}))
 return result
